import json,hashlib,re,csv
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parent
NOW=datetime.now(timezone.utc).isoformat()
A=json.loads((ROOT/'reward-source-audit.json').read_text(encoding='utf-8'))
# A successful HTTP response is not necessarily usable evidence.
for s in A:
 if s.get('status')=='fetched' and s.get('characters',0)<300:s['status']='insufficient_text'
(ROOT/'reward-source-audit.json').write_text(json.dumps(A,ensure_ascii=False,indent=2),encoding='utf-8')
S={x['url']:x for x in A}
def source(url,kind='issuer',note=''):
 s=S.get(url,{})
 return {'url':url,'kind':kind,'access':s.get('status','previous_or_web_read'),'content_file':s.get('content_file'),'sha256':s.get('content_sha256'),'note':note}
registry=[]
def add(name,year,eco,rules,result,level,urls,lesson,unknown,amount=None,recipients=None,event_date=None,operation='historical_product_evidence',tags=()):
 registry.append({'project':name,'reward_year':year,'event_date':event_date,'ecosystems':eco,'rules_summary':rules,'payout_summary':result,'payout_evidence_level':level,'reported_amount':amount,'reported_recipients':recipients,'current_operation_check':operation,'sources':[source(u) if isinstance(u,str) else u for u in urls],'agent_lesson':lesson,'unknowns':unknown,'tags':list(tags),'fine_tuning_eligible':False,'review_status':'source_checked_partial_dossier','reviewed_at':NOW})
# Retain earlier facts; do not translate allocation fields into paid totals.
old=json.loads((ROOT.parent/'historical-cases.json').read_text(encoding='utf-8'))['cases']
