 out=c.get('outcome') or {};rep=c.get('reported_outcome') or {}
 result=out.get('statement') or ('Опубліковано аналіз claims; незалежний запит ще не відтворено.' if rep else 'Підсумок фактичних виплат у зібраному досьє ще не підтверджений.')
 add(c['project'],c['year'],['Cosmos'] if c['project']=='Celestia' else [],c['finding'],result,levels.get(c['project'],'allocation_or_rules_only'),[source(x['url'],'published_analysis' if 'dragonfly' in x['url'] else 'issuer') for x in c['sources']],c['product_lesson'],['Точні виплати та кількість адрес потребують окремого аудиту.','Фактичні витрати та чистий результат учасників невідомі.','Поточна працездатність не перевірена живою транзакцією.'],tags=[c['category']])
 registry[-1]['legacy_case']=c
 registry[-1]['reported_claim_analysis']=rep or None
 registry[-1]['operation_evidence']=c.get('mainnet')
