models=[]
idx=json.loads((ROOT/'dune-model-index.json').read_text())
for p in idx['paths']:
 if '/projects/' not in p or not p.endswith('.sql'):continue
 f=ROOT/'dune-models'/p.split('/')[-1]
 if not f.exists():continue
 t=f.read_text();m=re.search(r"'([^']+)'\s+AS\s+project",t,re.I);tok=re.search(r"'([^']+)'\s+AS\s+token_symbol",t,re.I)
 models.append({'project_key':m.group(1) if m else p.split('/')[-1].split('_ethereum_')[0],'model_url':'https://github.com/duneanalytics/spellbook/blob/main/'+p,'local_model':str(f.relative_to(ROOT)),'token':tok.group(1) if tok else None,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'query_executed':False,'payout_verified':False,'review_status':'onchain_model_available_not_results'})
(ROOT/'claim-model-candidates.json').write_text(json.dumps(models,ensure_ascii=False,indent=2),encoding='utf-8')
# Curated extensions remain separate and survive every rebuild.
exp_audit_path=ROOT/'expansion-source-audit.json'
exp_audit={x['url']:x for x in json.loads(exp_audit_path.read_text(encoding='utf-8'))} if exp_audit_path.exists() else {}
seen={x['project'].casefold() for x in registry}
for path in sorted(ROOT.glob('expansion-curated-*.json')):
 for row in json.loads(path.read_text(encoding='utf-8-sig')):
  key=row['project'].casefold()
  if key in seen:raise ValueError('Duplicate issuer: '+row['project'])
  seen.add(key)
  for src in row['sources']:
   ev=exp_audit.get(src['url'],{})
   src['direct_fetch_status']=ev.get('status','not_attempted')
   if ev.get('status')=='fetched':
    src.update(access='direct_text_fetched',content_file=ev['content_file'],sha256=ev['content_sha256'],hash_scope='extracted_text_utf8')
  registry.append(row)
for row in registry:
 row.setdefault('scope_status','sale_comparison_excluded_target' if row['payout_evidence_level']=='sale_not_reward' else 'historical_candidate_current_operation_not_verified')
