 w=csv.DictWriter(f,fieldnames=keys);w.writeheader()
 for x in registry:w.writerow({**{k:x.get(k) for k in keys[:-1]},'ecosystems':'; '.join(x['ecosystems']),'unknowns':'; '.join(x['unknowns']),'source_urls':' | '.join(s['url'] for s in x['sources'])})
